def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    fg = {v for row in grid for v in row if v != bg and v != 2}
    for color in fg:
        # Only interpolate a row/column that contains an actual contiguous stroke.
        active_rows = {r for r in range(h) if any(grid[r][c] == color and grid[r][c+1] == color for c in range(w-1))}
        active_cols = {c for c in range(w) if any(grid[r][c] == color and grid[r+1][c] == color for r in range(h-1))}
        for r in active_rows:
            positions = [c for c in range(w) if grid[r][c] == color]
            for a,b in zip(positions, positions[1:]):
                for c in range(a+1,b):
                    if grid[r][c] == bg: out[r][c] = 2
        for c in active_cols:
            positions = [r for r in range(h) if grid[r][c] == color]
            for a,b in zip(positions, positions[1:]):
                for r in range(a+1,b):
                    if grid[r][c] == bg: out[r][c] = 2
        # Fill a missing corner when it continues both an active horizontal and vertical stroke.
        for r in range(h):
            for c in range(w):
                if grid[r][c] != bg: continue
                horiz = ((c>0 and grid[r][c-1]==color) or (c+1<w and grid[r][c+1]==color))
                vert = ((r>0 and grid[r-1][c]==color) or (r+1<h and grid[r+1][c]==color))
                if horiz and vert and r in active_rows and c in active_cols:
